lines=['# Resources catalog','', '## Summary','', '40 original paper PDFs, 3 specified web articles, 4 downloaded datasets plus 1 generated arithmetic suite, and 6 official code repositories. All explicitly supplied sources are local. Supplemental search coverage is incomplete: 37 of 233 paper-finder entries are available after title reconciliation; 196 downloads remain unavailable after retries. This is a resource handoff, not completed model experiments.','', '## Papers','', '| Title | Authors | Year | Local file | Key information |','|---|---|---:|---|---|']
